sys_ux_client_script.script:
async function handler({ api, event, helpers, imports, state }) {
    // console.log("Handler function started.");

    if (!helpers.snHttp || typeof helpers.snHttp !== "function") {
        console.error("Error: helpers.snHttp is not properly initialized or callable.");
        return;
    }

    const pageId = 'e2e14f02c37f1e500ced12f1b4013102';
    api.context.session.user.sys_id
    // console.log(`Current page ID: ` , api.context.session.user.sys_id);
    // Map page IDs to categories
    const pageCategoryMap = {
        'e2e14f02c37f1e500ced12f1b4013102': 'Plugin Management',

    };

    // Get the category based on the current page
    const category = pageCategoryMap[pageId] || null;
    // console.log(`Resolved category: ${category}`);

    if (!category) {
        console.error("No valid category found. Aborting request.");
        return;
    }

    try {


        // Constructing the API request payload
        const requestBody = JSON.stringify({ category });
        // console.log("Sending API request with payload:", requestBody);

        const response = await helpers.snHttp("/api/985627/value_builder_task8", {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
            },
            body: requestBody,
        });

        // console.log("API response received:", response);

        // console.log("Removing loading notification.");
        api.emit("NOW_UXF_PAGE#REMOVE_NOTIFICATIONS", {
            items: ["processing"]
        });

        if (response.status === 200 || (response.response && response.response.result && response.response.result.status === "success")) {
            // console.log("API response indicates success.");
            const result = response.response.result;

            console.log("Parsed API response result:", result);

            const createdTasks = result.created_tasks?.length ? result.created_tasks.join(", ") : "No tasks created";
            const updatedTasks = result.updated_tasks?.length ? result.updated_tasks.join(", ") : "No tasks updated";
            const categoryProcessed = result.category_processed || category;



            let notificationContent = `Value builder task updated successfully`;

            api.emit("NOW_UXF_PAGE#ADD_NOTIFICATIONS", {
                items: [
                    {
                        id: "success_notification",
                        status: "positive",
                        icon: "info-circle-outline",
                        content: await helpers.translate(notificationContent),
                        action: { type: "dismiss" },
                        duration: 3000,

                    },
                ],
            });
        } else {
            console.error("API response indicates failure:", response);

            console.log("Emitting error notification.");
            api.emit("NOW_UXF_PAGE#ADD_NOTIFICATIONS", {
                items: [
                    {
                        id: "error_notification",
                        status: "critical",
                        icon: "info-circle-outline",
                        content: await helpers.translate("Failed to process tasks"),
                        action: { type: "dismiss" },
                    },
                ],
            });
        }
    } catch (error) {
        console.error("API Call Failed:", error.message || error);

        if (error.response) {
            console.error("Error Response Data:", error.response);
        } else if (error.data) {
            console.error("Error Data:", error.data);
        }

        console.log("Emitting error notification for unexpected failure.");
        api.emit("NOW_UXF_PAGE#ADD_NOTIFICATIONS", {
            items: [
                {
                    id: "error_notification",
                    status: "critical",
                    icon: "info-circle-outline",
                    content: await helpers.translate("An error occurred while processing tasks"),
                    action: { type: "dismiss" },
                },
            ],
        });
    }

    console.log("Handler function execution completed.");
}
